":null,"production_status":"pending"}],"nodes":[{"title":{"ko-KR":"외출 전에 무엇을 먼저 들어야 할까요?","zh-CN":"出门前要先听懂什么？"},"content":{"lead":{"ko-KR":"날씨가 좋다는 말만으로는 준비물을 정할 수 없어 시간대와 변화를 들어야 합니다.","zh-CN":"只知道天气不错还不能决定带什么；要听清时段、变化和准备建议。"},"coach":{"ko-KR":"점수 없는 장면 진단 정답만 필수이며 마지막 과제 설명은 자율 활동입니다.","zh-CN":"答对不计分场景诊断即完成；复述任务为自主展示。"},"targets":[{"ko":"오늘 날씨가 어때요?","zh":"询问天气"},{"ko":"오늘은 맑고 따뜻합니다.","zh":"播报今天"},{"ko":"내일 오후에는 비가 옵니다.","zh":"播报明天"},{"ko":"우산을 준비하세요.","zh":"给出建议"}],"nextNode":"weather-and-seasons","finalOutput":{"ko-KR":"계절, 오늘, 시간대 대조, 내일과 준비 안내를 포함한 50~70초, 7~9문장의 도시 날씨 안내입니다.","zh-CN":"50—70秒、7—9句的城市天气播报，包含季节、今天、时段反差、明天和准备建议。"}},"node_code":"mission-map","node_type":"mission","sort_order":1,"module_code":"orientation","estimated_minutes":5},{"title":{"ko-KR":"계절, 시간대, 날씨와 준비물을 말덩이로 익히기","zh-CN":"把季节、时段、天气和准备物配成块"},"content":{"lead":{"ko-KR":"그림 확인, 기본형 듣기, 결합 따라 읽기와 시간대 문장 순서로 익힙니다. 음원은 제작 대기 중입니다.","zh-CN":"按看图辨认、点读原形、跟读搭配、放进时段句学习；全部音频待制作。"},"coach":{"ko-KR":"뜻 정답과 문장 낭독 확인이 필요하며 듣기와 그림 말하기는 자율 연습입니다.","zh-CN":"词义选对并确认朗读整句才完成；22词点读和看图快说为自主练习。"},"nextNode":"weather-grammar-tools","vocabulary":[{"ko":"계절","zh":"季节","pos":"名词","collocation":"무슨 계절이에요?"},{"ko":"봄","zh":"春天","pos":"名词","collocation":"봄에는 따뜻해요."},{"ko":"여름","zh":"夏天","pos":"名词","collocation":"여름에는 더워요."},{"ko":"가을","zh":"秋天","pos":"名词","collocation":"가을에는 시원해요."},{"ko":"겨울","zh":"冬天","pos":"名词","collocation":"겨울에는 추워요."},{"ko":"날씨","zh":"天气","pos":"名词","collocation":"날씨가 어때요?"},{"ko":"기온","zh":"气温","pos":"名词","collocation":"낮 기온"},{"ko":"아침","zh":"早晨","pos":"名词","collocation":"아침에는 맑아요."},{"ko":"낮","zh":"白天","pos":"名词","collocation":"낮에는 더워요."},{"ko":"밤","zh":"夜晚","pos":"名词","collocation":"밤에는 시원해요."},{"ko":"맑다","zh":"晴朗","pos":"形容词","collocation":"날씨가 맑아요."},{"ko":"흐리다","zh":"阴、阴沉","pos":"形容词","collocation":"날씨가 흐려요."},{"ko":"덥다","zh":"热","pos":"形容词","collocation":"낮에는 더워요."},{"ko":"춥다","zh":"冷","pos":"形容词","collocation":"밤에는 추워요."},{"ko":"따뜻하다","zh":"温暖","pos":"形容词","collocation":"맑고 따뜻해요."},{"ko":"시원하다","zh":"凉爽","pos":"形容词","collocation":"밤에는 시원해요."},{"ko":"비","zh":"雨","pos":"名词","collocation":"비가 와요."},{"ko":"눈","zh":"雪","pos":"名词","collocation":"눈이 와요."},{"ko":"바람","zh":"风","pos":"名词","collocation":"바람이 불어요."},{"ko":"우산","zh":"雨伞","pos":"名词","collocation":"우산을 준비하세요."},{"ko":"겉옷","zh":"外套","pos":"名词","collocation":"겉옷을 가져가세요."},{"ko":"준비하다","zh":"准备","pos":"动词","collocation":"우산을 준비하세요."}]},"node_code":"weather-and-seasons","node_type":"learn","sort_order":1,"module_code":"vocabulary","estimated_minutes":10},{"title":{"ko-KR":"날씨 변화를 자연스럽고 분명하며 격식 있게 말하기","zh-CN":"把天气变化说得自然、清楚、正式"},"content":{"lead":{"ko-KR":"덥다와 춥다를 활용하고 첨가와 대조를 구별한 뒤 격식체로 바꿉니다.","zh-CN":"先处理덥다/춥다，再区分相加与反差，最后切换正式播报体。"},"coach":{"ko-KR":"여섯 빈칸을 모두 맞혀야 하며 규칙 설명과 확장 활용은 자율 연습입니다.","zh-CN":"六项填空全部正确才完成；口头规则解释与扩展变形为自主练习。"},"nextNode":"forecast-pattern-lab","grammarCards":[{"form":"ㅂ 불규칙","rules":["元音起始词尾前ㅂ脱落并加우","더우+어요缩约为더워요","辅音词尾前保留ㅂ：덥지만、춥습니다","입다、잡다等规则动词不套用"],"source":{"ko-KR":"원고 §5.1; 기존 전자책 쪽수는 수동 확인이 필요합니다.","zh-CN":"母本§5.1；旧电子书精确页码待人工核对。"},"caution":{"ko-KR":"잘못: 덥어요. 모음 어미 앞에서는 더워요입니다.","zh-CN":"错误：덥어요；元音词尾前应写더워요。"},"examples":[{"ko":"여름에는 날씨가 더워요.","zh":"夏天天气很热。","audioId":"chapter-07-grammar-01-example-01","audioStatus":"pending"},{"ko":"낮에는 더워요. 바람도 불어요.","zh":"白天很热，也会刮风。","audioId":"chapter-07-grammar-01-example-02","audioStatus":"pending"},{"ko":"낮에는 따뜻하지만 밤에는 추워요.","zh":"白天暖和，但晚上很冷。","audioId":"chapter-07-grammar-01-example-03","audioStatus":"pending"}],"function":{"ko-KR":"더위와 추위를 자연스럽게 활용합니다.","zh-CN":"描述冷热时自然变化덥다/춥다。"},"comparison":{"ko-KR":"더워요와 추워요는 대화체, 덥습니다와 춥습니다는 격식체입니다.","zh-CN":"더워요/추워요用于日常对话；덥습니다/춥습니다用于正式播报。"}},{"form":"A/V-지만","rules":["词干后直接加지만","有无收音不改变-지만","ㅂ不规则词在辅音词尾前保留ㅂ","后项放更需注意的变化"],"source":{"ko-KR":"원고 §5.2; 기존 전자책 쪽수는 수동 확인이 필요합니다.","zh-CN":"母本§5.2；旧电子书精确页码待人工核对。"},"caution":{"ko-KR":"잘못: 더워지만. -지만은 덥-에 직접 붙습니다.","zh-CN":"错误：더워지만；-지만直接接덥-。"},"examples":[{"ko":"낮에는 덥지만 밤에는 시원해요.","zh":"白天热，但晚上凉快。","audioId":"chapter-07-grammar-02-example-01","audioStatus":"pending"},{"ko":"밤에는 시원하지만 비가 와요.","zh":"晚上凉快，但是会下雨。","audioId":"chapter-07-grammar-02-example-02","audioStatus":"pending"},{"ko":"낮에는 덥지만 밤에는 시원합니다.","zh":"白天热，但晚上凉快。","audioId":"chapter-07-grammar-02-example-03","audioStatus":"pending"}],"function":{"ko-KR":"대조되는 날씨 정보를 연결합니다.","zh-CN":"连接有反差的天气信息。"},"comparison":{"ko-KR":"-고는 첨가, -지만은 대조를 나타냅니다.","zh-CN":"-고表示相加；-지만表示反差。"}},{"form":"A/V-습니다/ㅂ니다","rules":["无收音词干加-ㅂ니다","有收音词干加-습니다","ㄹ收音脱落后加-ㅂ니다","ㅂ不规则词在辅音词尾前保留ㅂ"],"source":{"ko-KR":"원고 §5.3; 기존 전자책 쪽수는 수동 확인이 필요합니다.","zh-CN":"母本§5.3；旧电子书精确页码待人工核对。"},"caution":{"ko-KR":"잘못: 오습니다. 오- 뒤에는 -ㅂ니다를 붙여 옵니다입니다.","zh-CN":"错误：오습니다；无收音词干오-接-ㅂ니다写作옵니다。"},"examples":[{"ko":"오늘 서울은 맑습니다.","zh":"今天首尔晴朗。","audioId":"chapter-07-grammar-03-example-01","audioStatus":"pending"},{"ko":"내일 오전에는 흐리고 오후에는 비가 옵니다.","zh":"明天上午阴，下午有雨。","audioId":"chapter-07-grammar-03-example-02","audioStatus":"pending"},{"ko":"토요일 부산은 맑고 따뜻합니다.","zh":"星期六釜山晴朗而温暖。","audioId":"chapter-07-grammar-03-example-03","audioStatus":"pending"}],"function":{"ko-KR":"청중에게 날씨를 격식 있게 안내합니다.","zh-CN":"面向听众正式播报天气。"},"comparison":{"ko-KR":"비가 와요는 대화체이고 비가 옵니다는 격식체입니다.","zh-CN":"비가 와요是同学间礼貌体；비가 옵니다是正式播报体。"}},{"form":"A/V-고","rules":["词干后直接加고","有无收音都不改变-고","ㅂ不规则词在辅音词尾前保留ㅂ","本课聚焦天气状态相加"],"source":{"ko-KR":"원고 §5.4; 기존 전자책 쪽수는 수동 확인이 필요합니다.","zh-CN":"母本§5.4；旧电子书精确页码待人工核对。"},"caution":{"ko-KR":"잘못: 맑아고. 맑-에 고를 붙여 맑고라고 씁니다.","zh-CN":"错误：맑아고；应取词干맑-加고。"},"examples":[{"ko":"오늘은 맑고 따뜻해요.","zh":"今天晴朗而温暖。","audioId":"chapter-07-grammar-04-example-01","audioStatus":"pending"},{"ko":"오전에는 흐리고 오후에는 맑아요.","zh":"上午阴，下午晴。","audioId":"chapter-07-grammar-04-example-02","audioStatus":"pending"},{"ko":"일요일 오전에는 흐리고 오후에는 비가 옵니다.","zh":"星期日上午阴，下午有雨。","audioId":"chapter-07-grammar-04-example-03","audioStatus":"pending"}],"function":{"ko-KR":"같은 시간대의 두 날씨 정보를 나열합니다.","zh-CN":"并列同一时段的两项天气。"},"comparison":{"ko-KR":"-고는 날씨를 더하고 -지만은 대조를 강조합니다.","zh-CN":"-고相加天气，-지만突出反差。"}}]},"node_code":"weather-grammar-tools","node_type":"learn","sort_order":1,"module_code":"grammar","estimated_minutes":18},{"title":{"ko-KR":"날씨 문장을 순서 있는 안내로 만들기","zh-CN":"从天气单句变成有顺序的播报"},"content":{"lead":{"ko-KR":"계절, 날씨 나열과 시간대 대조를 연습한 뒤 다섯 안내 문장을 배열합니다.","zh-CN":"先练季节、并列天气和时段反差，再排列五个完整播报语块。"},"coach":{"ko-KR":"다섯 문장 배열 정답만 필수이며 바꿔 말하기와 개인 표현은 자율 연습입니다.","zh-CN":"五语块排序全对才完成；替换、快答和个人表达为自主练习。"},"nextNode":"weather-before-going-out","orderItems":["낮에는 덥지만 밤에는 시원합니다.","오늘은 맑고 따뜻합니다.","우산을 준비하세요.","서울 날씨입니다.","내일 오후에는 비가 옵니다."],"personalFrames":["___에는 더워요/추워요/따뜻해요/시원해요.","오늘은 ___고 ___어요.","___에는 ___지만 ___에는 ___어요."],"replacementSets":[["여름에는 더워요.","겨울에는 추워요.","봄에는 따뜻해요.","가을에는 시원해요."],["맑고 따뜻해요.","흐리고 시원해요.","비가 오고 바람이 불어요."],["낮에는 덥지만 밤에는 시원해요.","아침에는 흐리지만 오후에는 맑아요.","내일은 흐리지만 따뜻합니다."]]},"node_code":"forecast-pattern-lab","node_type":"practice","sort_order":1,"module_code":"patterns","estimated_minutes":12},{"title":{"ko-KR":"변화를 듣고 준비물 정하기","zh-CN":"先听变化，再决定带什么"},"content":{"lead":{"ko-KR":"전체를 읽고 음원 제작 후 들은 뒤 문장별로 따라 읽고 역할을 바꿉니다.","zh-CN":"先整段默读，待音频制作后整段听，再逐句跟读、隐藏中文和切换角色。"},"coach":{"ko-KR":"날씨 사실과 자연스러운 응답을 모두 맞혀야 하며 바꿔 말하기와 시험 녹음은 자율 연습입니다.","zh-CN":"事实组合题和自然回应题都答对才完成；信息替换和双角色试录为自主练习。"},"nextNode":"listen-and-forecast","dialogueScenes":[{"lines":[{"ko":"오늘 날씨가 어때요?","zh":"今天天气怎么样？","speaker":"지민"},{"ko":"아침에는 맑고 따뜻해요.","zh":"早上晴朗又温暖。","speaker":"준호"},{"ko":"낮에도 따뜻해요?","zh":"白天也暖和吗？","speaker":"지민"},{"ko":"아니요. 낮에는 더워요. 바람도 불어요.","zh":"不。白天很热，也会刮风。","speaker":"준호"},{"ko":"밤에는 어때요?","zh":"晚上怎么样？","speaker":"지민"},{"ko":"밤에는 시원하지만 비가 와요.","zh":"晚上凉快，但是会下雨。","speaker":"준호"},{"ko":"그럼 우산이 필요해요?","zh":"那需要雨伞吗？","speaker":"지민"},{"ko":"네, 우산을 가져가세요.","zh":"是的，请带上雨伞。","speaker":"준호"}],"title":{"ko-KR":"금요일 방과 전 학교 로비","zh-CN":"周五放学前的学校大厅"},"people":{"ko-KR":"지민과 준호, 같은 반 친구","zh-CN":"智敏与俊浩，同班同学"},"audioId":"chapter-07-dialogue-main","purpose":{"ko-KR":"오늘 아침, 낮과 밤 날씨를 확인하고 우산을 준비할지 정합니다.","zh-CN":"确认今天早晨、白天和夜间天气并决定是否带伞。"},"audioStatus":"pending"},{"lines":[{"ko":"내일 날씨가 어때요?","zh":"明天天气怎么样？","speaker":"소라"},{"ko":"오전에는 흐리고 오후에는 맑아요.","zh":"上午阴，下午晴。","speaker":"민수"},{"ko":"기온은 어때요?","zh":"气温怎么样？","speaker":"소라"},{"ko":"낮에는 따뜻하지만 밤에는 추워요.","zh":"白天暖和，但是晚上很冷。","speaker":"민수"},{"ko":"그럼 겉옷이 필요해요?","zh":"那需要外套吗？","speaker":"소라"},{"ko":"네, 겉옷을 가져가세요.","zh":"是的，请带上外套。","speaker":"민수"}],"title":{"ko-KR":"금요일 오후 교실 창가","zh-CN":"周五下午的教室窗边"},"people":{"ko-KR":"소라와 민수, 같은 반 친구","zh-CN":"素拉与敏秀，同班同学"},"audioId":"chapter-07-dialogue-alt","purpose":{"ko-KR":"내일 오전과 오후 날씨, 낮과 밤 기온을 확인하고 겉옷을 준비할지 정합니다.","zh-CN":"确认明天上午下午天气和昼夜温差并决定是否带外套。"},"audioStatus":"pending"}]},"node_code":"weather-before-going-out","node_type":"mission","sort_order":1,"module_code":"dialogue","estimated_minutes":12},{"title":{"ko-KR":"내일 오후를 듣고 1분 안내 완성하기","zh-CN":"听出明天下午，再完成一分钟播报"},"content":{"lead":{"ko-KR":"듣기 원고, 정답, 쉼과 객체 키는 서버에서만 관리합니다.","zh-CN":"私有听力只显示待制作音频控件和问题；脚本、答案、停顿与对象键只在服务端。"},"coach":{"ko-KR":"음원이 제작되어 재생 가능하고 듣기 정답과 말하기 조건을 모두 충족해야 합니다.","zh-CN":"音频制作并可播放后听力答对，同时提交满足时长、句数、五类信息与语体要求的录音才完成。"},"nextNode":"city-weather-card","speakingTask":{"duration":"50—70秒","formalStyle":true,"targetSeconds":60,"maximumSentences":9,"minimumSentences":7,"pronunciationScore":false,"requiredInformation":["城市与季节","今天两项-고天气","一次-지만时段反差","明天正式预报","有依据的准备建议"]}},"node_code":"listen-and-forecast","node_type":"practice","sort_order":1,"module_code":"listen_speak","estimated_minutes":15},{"title":{"ko-KR":"짧은 날씨 안내문을 읽고 새로운 도시 예보 쓰기","zh-CN":"读简短天气公告，写新的城市预报"},"content":{"lead":{"ko-KR":"요일과 시간대에 따라 읽고 준비 안내가 날씨 근거와 연결되게 씁니다.","zh-CN":"按星期和时段读取信息，让准备建议能回到正文天气依据。"},"coach":{"ko-KR":"읽기 세 문제와 5~6문장, 다섯 정보, 격식체 및 자기 점검을 모두 완성합니다.","zh-CN":"三道阅读题全对，提交5—6句、五类信息齐全、主体正式体并完成五维量规自查。"},"reading":{"lines":["토요일 부산은 맑고 따뜻합니다.","낮에는 덥지만 밤에는 시원합니다.","일요일 오전에는 흐리고 오후에는 비가 옵니다.","바람도 붑니다.","우산을 준비하세요."],"title":"부산 주말 날씨"},"writing":{"frame":"___ 날씨입니다. → ___에는 ___습니다. → 오늘은 ___고 ___습니다. → ___에는 ___지만 ___에는 ___습니다. → 내일 ___에는 ___습니다. → ___을/를 준비하세요.","rubric":["信息完整","核心语法","建议依据","可理解度","格式与语气"],"example":"서울 날씨입니다. 겨울에는 춥습니다. 오늘은 맑고 시원합니다. 낮에는 맑지만 밤에는 눈이 옵니다. 내일 아침에도 춥습니다. 겉옷을 준비하세요.","audience":{"ko-KR":"같은 반 친구","zh-CN":"同班同学"},"sentences":"5—6","requirements":["城市与季节特征","今天两项天气","时段反差","明天正式预报","有依据的准备建议"]},"nextNode":"can-do-check"},"node_code":"city-weather-card","node_type":"practice","sort_order":1,"module_code":"read_write","estimated_minutes":13},{"title":{"ko-KR":"다른 사람이 안내를 듣고 준비할 수 있을까요?","zh-CN":"我能让别人根据播报做好准备吗？"},"content":{"lead":{"ko-KR":"자율 복습은 필수 증거가 아니며 종합 문제와 다섯 점검을 기록합니다.","zh-CN":"自主复习展示不作为强制证据；综合多选与五项自查由合同记录。"},"canDo":[{"ko":"계절과 시간대에 맞는 날씨 표현을 사용할 수 있어요.","zh":"我能用合适词汇描述季节和时段天气。"},{"ko":"덥다와 춥다를 해요체와 격식체로 바르게 바꿀 수 있어요.","zh":"我能正确使用덥다/춥다的日常体和正式体。"},{"ko":"날씨 정보를 더할 때 -고, 대조할 때 -지만을 사용할 수 있어요.","zh":"我能用-고相加天气，用-지만表达反差。"},{"ko":"생활 날씨 안내문을 읽고 5~6문장의 새로운 예보를 쓸 수 있어요.","zh":"我能读懂天气公告并写5—6句新预报。"},{"ko":"오늘과 내일, 시간대 변화와 준비 안내를 넣어 50~70초 동안 날씨를 안내할 수 있어요.","zh":"我能加入今天、明天、时段变化和准备建议，完成50—70秒天气播报。"}],"coach":{"ko-KR":"종합 문제 정답과 다섯 점검 및 복습 위치 또는 none 기록이 필요합니다.","zh-CN":"综合多选答对，五项自查全部回应并记录返回节点或none后完成。"},"chapterTest":"korean-level-one-07","remediation":[{"node":"weather-and-seasons","reason":"词汇"},{"node":"weather-grammar-tools","reason":"语法"},{"node":"weather-before-going-out／listen-and-forecast","reason":"理解"},{"node":"listen-and-forecast","reason":"表达"},{"node":"city-weather-card","reason":"读写"}]},"node_code":"can-do-check","node_type":"review","sort_order":1,"module_code":"review","estimated_minutes":8}],"chapter":{"id":"7a631692-3093-41da-acba-e4c8e891fb00","goal":{"ko-KR":"ㅂ 불규칙, 날씨 상태 -고, 대조 -지만과 격식체를 사용하여 50~70초, 7~9문장의 도시 날씨 안내를 합니다.","zh-CN":"使用ㅂ不规则、天气状态-고、转折-지만和正式体，完成50—70秒、7—9句的城市天气播报。"},"slug":"weather","title":{"ko-KR":"날씨가 어때요?","zh-CN":"天气怎么样？"},"status":"draft","scenario":{"ko-KR":"지민과 준호는 오늘의 시간대별 날씨를 보고 우산을 준비할지 정하고 소라와 민수는 내일 예보를 보고 겉옷을 준비할지 정합니다.","zh-CN":"智敏和俊浩查看当天分时天气决定是否带伞；素拉和敏秀查看次日预报决定是否带外套。"},"audio_status":"pending","image_status":"pending","chapter_number":7,"source_revision":"UPLY BOOK 第07课 날씨가 어때요.md @ 2026-08-18 / sha256:4104c3438ebb9b4f892396002a5c91965a8a9b09f7bf504aba6c4a92b670a52c","editorial_stat